mermaid:
---
config:
  flowchart:
    curve: linear
---
graph TD;
	__start__([<p>__start__</p>]):::first
	plan(plan)
	enqueue(enqueue)
	validate_gap(validate_gap)
	enqueue_rank(enqueue_rank)
	rank_gap(rank_gap)
	collect(collect)
	__end__([<p>__end__</p>]):::last
	__start__ --> plan;
	director\3afinalize --> enqueue;
	enqueue -.-> enqueue_rank;
	enqueue -.-> validate_gap;
	enqueue_rank -.-> collect;
	enqueue_rank -.-> rank_gap;
	plan --> director\3aload_known;
	rank_gap -.-> collect;
	validate_gap -.-> enqueue_rank;
	collect --> __end__;
	rank_gap -.-> rank_gap;
	validate_gap -.-> validate_gap;
	subgraph director
	director\3aload_known(load_known)
	director\3acollect_pending(collect_pending)
	director\3adedup(dedup)
	director\3afinalize(finalize)
	director\3acollect_pending --> director\3adedup;
	director\3adedup --> director\3afinalize;
	director\3aload_known --> director\3acollect_pending;
	end
	classDef default fill:#f2f0ff,line-height:1.2
	classDef first fill-opacity:0
	classDef last fill:#bfb6fc
